INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project B', 'Project B is a free multiplayer browser shooter that doesn''t require any registration to play. It contains two game modes: deathmatch and killrace. In deathmatch, players are ranked based on their amount of kills. In killrace, the player with the least amount of kills is eliminated after every round.' FROM games WHERE igdb_id = 240081 ON CONFLICT (game_id, language_code) DO NOTHING;
