INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RoboSquad Revolution', 'Welcome to the Revolution, where you are an insurgent robot marching to the beat of your own motherboard in the name of rebellion. Level up your components and rewrite the future of AI, one Hologram Throwdown at a time. Well what are you waiting for, metalhead? Join a squad for free today!' FROM games WHERE igdb_id = 247288 ON CONFLICT (game_id, language_code) DO NOTHING;
