INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Incident In Oakwood', 'An urban explorer ventures out to an abandoned cabin in the woods that was involved in an unsolved alien abduction case from the 1960s. UFO activity and sightings of extraterrestrial beings have been reported in the area of Oakwood forest dating back all the way to the 1950s.' FROM games WHERE igdb_id = 285413 ON CONFLICT (game_id, language_code) DO NOTHING;
