INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Draw', 'Welcome to the world of Draw, a 2D sidescroller and visual novel! Armed with nothing but a pencil, play as "Stickman" as you explore a brand-new world. Solve puzzles by drawing into the game, meet new friends while dodging scribble monsters, and make memories that’ll never be erased!' FROM games WHERE igdb_id = 258014 ON CONFLICT (game_id, language_code) DO NOTHING;
