INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digs', 'Defend your valuable chest in randomly generated maps with various towers, traps and obstacles to modify the path that the enemies must follow in "Digs", the ultimate rogue-like tower defense game. Experience unique mechanics, upgrade your defenses and face off against challenging enemies' FROM games WHERE igdb_id = 236753 ON CONFLICT (game_id, language_code) DO NOTHING;
