INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fatal-frame-mask-of-the-lunar-eclipse', 217577, '2023-03-09', 68, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6065.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1vdy.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fatal Frame: Mask of the Lunar Eclipse', 'When the protagonists were children, they visited the isolated island of "Rogetsu Isle" to celebrate the Rogetsu Festival. In the midst of the celebrations, they suddenly disappeared. The game begins when the girls decide to go back and visit the island again in search of their lost memories of that day.
