INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spread: Transmission', 'Spread: Transmission is a turn-based strategy board game for up to eight players. Players take turns charging cells. Once a cell is fully charged it will spread and take over adjacent cells. Last player standing wins. There are multiple game modes called "Labs" that can be freely combined and customized. Players can play on one of the over 20 boards included with the game or design and play on their own boards.' FROM games WHERE igdb_id = 241387 ON CONFLICT (game_id, language_code) DO NOTHING;
