INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Village Tycoon: Farm City Simulator', 'Village Tycoon: Farm City Simulator is a fun and addictive farming simulation game that challenges players to develop their farming capabilities and turn their small village into a bustling metropolis. With beautiful and fun buildings, expansions, and a variety of crops to grow, players must manage their farmfields, produce goods, and deliver orders to their citizens and neighbors to keep them happy and earn cash and XP.' FROM games WHERE igdb_id = 275035 ON CONFLICT (game_id, language_code) DO NOTHING;
