INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Let''s Sing 2024', 'Let’s Sing 2024 brings a thrilling new karaoke experience to your living room. Enjoy chartbreaking hits and all-time classics that are guaranteed to make you sing at the top of your lungs. Step into the spotlight with the brand new career mode and rise to stardom. Become a VIP and test your vocal range with many more songs online. Experience seasonal events online with Let''s Sing Fest and join the never-ending karaoke party alone or with friends while you play with people across the globe.' FROM games WHERE igdb_id = 261154 ON CONFLICT (game_id, language_code) DO NOTHING;
