INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'It Is Coming', 'It Is Coming is a first-person low-poly collectathon inspired by Garry''s Mod PNG killer NPCs. You play as the next poor lad to get abducted and brought to Planet Camebox. You''ll go through maps while collecting Orbs and avoiding contact with whichever anomaly is hunting you down. Look out for the random events, they can help and harm you. Collecting more orbs unlocks more anomalies to choose from, and getting high ranks unlocks more maps.' FROM games WHERE igdb_id = 335665 ON CONFLICT (game_id, language_code) DO NOTHING;
