INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NeuroNet: Mendax Proxy', 'NeuroNet is a ''Reigns'' inspired story-driven adventure where your choices will decide the fate of a cyberpunk city. As a new A.I, created to manage the city of Catena, you have the power to shape its future and its people. But where will your choices lead them, into prosperity or ruin?' FROM games WHERE igdb_id = 147903 ON CONFLICT (game_id, language_code) DO NOTHING;
