INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jake Everest 2: Gunung Padang The Unseen Civilization', 'Embark on another epic journey with adventurer and archaeologist Jake Everest! His latest endeavor leads him to a mysterious object inscribed with ancient runes! He boards a plane to investigate the connection when he recognizes matching runes at the Gunung Padang archaeological site. His efforts alongside the archaeological team will lead them to discover lost secrets beyond anything they ever imagined! Come along for a match-3 journey for all time!' FROM games WHERE igdb_id = 258814 ON CONFLICT (game_id, language_code) DO NOTHING;
