INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toy Rider: Racing Game', 'Toy Rider is a mobile car racing game, what makes it different from a typical car racing game is, it is not just about speed it is about balancing, timing, proper use of power-ups & proper speed! The game is inspired by the Table Top Racing & Micromachine game but with lots of upgrades and improvements. One of the best offline racing game' FROM games WHERE igdb_id = 213698 ON CONFLICT (game_id, language_code) DO NOTHING;
