INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Defectum', 'Defectum is a virtual reality (VR) experience that seeks to express and give players a sense of the fear of failure by utilizing and visualizing my personal experiences and transforming them into a VR experience. Players are given the opportunity to take a “walk in my shoes” and view the world through an intimate lens—they will face feelings and emotions such as anxiety, unease, and a loss of hope and are encouraged to take their time to explore and experience the visuals that are presented to them.' FROM games WHERE igdb_id = 249414 ON CONFLICT (game_id, language_code) DO NOTHING;
