INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Evocation', 'In a small cul-de-sac neighborhood lives a group of 3 middle-school aged friends. Together, they share a treehouse where they hang out after school. All is well, until one day they notice a portrait of themselves hung up on the wall with a fourth person they''ve never seen before. Who could this mysterious boy be, and how did he show up in their lives? The answer, once known, may never be remembered...' FROM games WHERE igdb_id = 302483 ON CONFLICT (game_id, language_code) DO NOTHING;
