INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Raccoo Venture', 'Raccoo Venture is a 3D platform adventure and collect-a-thon that brings a playful atmosphere inspired by the golden classics from 90s. Raccoo is the last heir of the Guardian Power, who for many years protected the Sacred Relics. Now he must protect the world from the dangerous Tattooed Tatus which are going to steal the mythical jewel and bring chaos to the land. Raccoo must defeat enemies, solve secrets and puzzles while exploring the World of Verta, discovering magic items and new costumes that will help him in this journey in a search for the stolen Relic Pieces.' FROM games WHERE igdb_id = 113876 ON CONFLICT (game_id, language_code) DO NOTHING;
