INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Replay Boys', 'Band emergency! This was supposed to be Hannah’s day off, but now she’s been roped into managing The Replay Boys, an up-and-coming boy band. Make choices to stoke multi-timeline romances, keep the band from killing each other, and fight a resurrected ’80s pop star ghost. Can you manage?' FROM games WHERE igdb_id = 259188 ON CONFLICT (game_id, language_code) DO NOTHING;
