INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sunya', 'An enchanting pixel art platformer that embarks you on a quest to find and wield the immense powers of the four elements: air, earth, water, and fire. Players are granted the ability to transform into different elemental forms at will, enabling them to adapt to and overcome intricate obstacles.' FROM games WHERE igdb_id = 253006 ON CONFLICT (game_id, language_code) DO NOTHING;
