INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Volleygon', 'Volleygon is a raucous 2-on-2 anti-gravity showdown where geometric shapes flying through space take center stage! Utilize the ceiling and floor to bounce, lob, and smash the ball into your opponent''s zone! Just be careful as the ball can change gravity on a whim, but so can your opponents!' FROM games WHERE igdb_id = 237689 ON CONFLICT (game_id, language_code) DO NOTHING;
