INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-quintessential-quintuplets-gotopazu-story', 237674, '2023-06-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7oqi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2pva.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Quintessential Quintuplets: Gotopazu Story', 'Gotopazu, the October 27, 2020-released smartphone game based on The Quintessential Quintuplets, comes to consoles in the form of memorial stories. The console version is developed by MAGES., developers of The Quintessential Quintuplets ∬: Summer Memories Also Come in Five and The Quintessential Quintuplets the Movie: Five Memories of My Time with You. It features the first year’s worth of memorial stories from Gotopazu for all five quintuplets, fully voiced across 24 volumes. There are also over 500 illustrations. And the Illustration Book Set editions are a must-have item for diehard fans.' FROM games WHERE igdb_id = 237674 ON CONFLICT (game_id, language_code) DO NOTHING;
