INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cyber-dreamscape-battle-deckers-2199', 395830, '2023-08-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobttr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc12ou7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cyber Dreamscape Battle-Deckers 2199', 'It''s some time in the early 2000s, and Cyber Dreamscape Battle-Deckers 2199 is a digital-only card game that''s developed a vibrant and loyal community thanks to its freedom of character expression and the giant game cabinets it''s played on. Even in your small US college town, there are players who meet and trade matches at the nearby city mall. For better or worse, the game shop in the mall is the only location close by with an officially-sanctioned CDBD battle arena setup. This has let all kinds of hyper-local tournaments and events pop up at the game shop, with all kinds of players showing up to participate. Unfortunately, it''s not all fun and games when not everyone in the community gets along or plays fair- even in a game where you can spectate a brawl between a slime-girl made of bubblegum and a wrestler in a teddy bear mask..!' FROM games WHERE igdb_id = 395830 ON CONFLICT (game_id, language_code) DO NOTHING;
