INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Colossal Cave VR', 'Acclaimed game designer Roberta Williams revives Colossal Cave as a retro, point-&-click, cave exploration puzzler. Based on the original 1970’s design by Will Crowther & Don Woods this VR update maintains its vintage charm, while revitalizing it for modern gamers.' FROM games WHERE igdb_id = 253587 ON CONFLICT (game_id, language_code) DO NOTHING;
