INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beyond the Long Night', 'Beyond the Long Night is a whimsical and chaotic twin-stick shooting roguelike adventure! Explore The Dark Mountain - a subterranean world full of monsters, secrets and lovable characters. Puzzle, upgrade and battle through three randomly generated areas to outrun a deadly storm and escape to the Overworld beyond. Uncover a trail of mysteries in this ancient kingdom of demigods and explorers, captured within an endless time loop.' FROM games WHERE igdb_id = 175804 ON CONFLICT (game_id, language_code) DO NOTHING;
