INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saint Maker', 'While attending a religious recollection, Holly Beltran experiences strange hauntings throughout the convent. At night, broken faced statues and whispered prayers haunt Holly’s dreams — before the recollection is over, Holly may have to face more than her own demons to come out alive.' FROM games WHERE igdb_id = 195551 ON CONFLICT (game_id, language_code) DO NOTHING;
