INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Commander: Zombie Wars', 'Embark on a gripping turn-based tactical game in a zombie-infested world. Choose survivors or zombies. Gather resources, recruit allies, and strategize against the undead or join the undead. Shape custom maps, and decide the fate of the world. Join the fight now!' FROM games WHERE igdb_id = 258969 ON CONFLICT (game_id, language_code) DO NOTHING;
