INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Little Sister''s Special Place', 'Our hero used to go to Akiba a lot when he was younger. It wasn''t to have fun, but for his little sister''s sake. One day, his younger sister is gifted a Christmas trip, and they spend time together as if they''re a couple. This is the delightful and touching love story of these two siblings.' FROM games WHERE igdb_id = 253712 ON CONFLICT (game_id, language_code) DO NOTHING;
